async page => {
  const aim = async (x, y) => {
    const v = await page.evaluate(() => window.AETHERBORNE.dims.view);
    await page.mouse.move(Math.round(x * v.scale + v.ox), Math.round(y * v.scale + v.oy));
  };
  const st = async () => JSON.parse(await page.evaluate(() => JSON.stringify(window.AETHERBORNE.state)));
  const doors = async () => await page.evaluate(() => ({ ...window.AETHERBORNE.room.doors }));
  const route = [];
  const visited = new Set();
  for (let i = 0; i < 40; i++) {
    let s = await st();
    if (s.mode !== 'playing') { route.push('mode:' + s.mode); break; }
    if (visited.has(s.room)) { route.push('loop@' + s.room); break; }
    visited.add(s.room);
    route.push(s.room + (s.cleared ? 'c' : 'u'));
    for (let k = 0; k < 60; k++) {
      const q = await st();
      if (q.mode !== 'playing') { route.push('mode:' + q.mode); break; }
      if (!q.list) break;
      const m = q.list.match(/@(\d+),(\d+)/);
      await aim(+m[1], +m[2]);
      const dx = +m[1] - q.px;
      const dy = +m[2] - q.py;
      const key = Math.abs(dx) > Math.abs(dy) ? (dx > 0 ? 'd' : 'a') : (dy > 0 ? 's' : 'w');
      await page.keyboard.down(key);
      await page.waitForTimeout(260);
      await page.keyboard.up(key);
      await page.keyboard.press('k');
      await page.keyboard.press('q');
      await page.waitForTimeout(260);
    }
    s = await st();
    if (s.mode !== 'playing') { route.push('mode:' + s.mode); break; }
    const ds = await doors();
    const target = Object.keys(ds).find(k => ds[k] && !visited.has(ds[k]));
    if (!target) { route.push('deadend:' + JSON.stringify(ds)); break; }
    const pt = { n: [570, 27], s: [570, 773], w: [27, 400], e: [1113, 400] }[target];
    await aim(pt[0], pt[1]);
    const key = { n: 'w', s: 's', w: 'a', e: 'd' }[target];
    await page.keyboard.down(key);
    await page.waitForTimeout(3500);
    await page.keyboard.up(key);
    await page.waitForTimeout(900);
  }
  return JSON.stringify({ route, s: await st() });
}

async page => {
  const aim = async (x, y) => {
    const v = await page.evaluate(() => window.AETHERBORNE.dims.view);
    await page.mouse.move(Math.round(x * v.scale + v.ox), Math.round(y * v.scale + v.oy));
  };
  const st = async () => JSON.parse(await page.evaluate(() => JSON.stringify(window.AETHERBORNE.state)));
  const press = async (keys, ms) => {
    for (const k of keys) await page.keyboard.down(k);
    await page.waitForTimeout(ms);
    for (const k of keys) await page.keyboard.up(k);
  };
  // Move toward (tx,ty) using both axes; stop when room changes or timeout.
  const walk = async (tx, ty, maxMs) => {
    const start = await st();
    let t = 0;
    while (t < maxMs) {
      const s = await st();
      if (s.room !== start.room || s.mode !== 'playing') return true;
      const dx = tx - s.px, dy = ty - s.py;
      const keys = [];
      if (Math.abs(dx) > 8) keys.push(dx > 0 ? 'd' : 'a');
      if (Math.abs(dy) > 8) keys.push(dy > 0 ? 's' : 'w');
      if (!keys.length) return false;
      const step = Math.min(400, Math.max(Math.abs(dx), Math.abs(dy)) * 9);
      await aim(tx, ty);
      await press(keys, step);
      t += step;
    }
    return false;
  };
  const route = [];
  const visited = new Set();
  for (let i = 0; i < 60; i++) {
    let s = await st();
    if (s.mode !== 'playing') { route.push('mode:' + s.mode); break; }
    if (visited.has(s.room)) { route.push('revisit:' + s.room); }
    visited.add(s.room);
    route.push(s.room + ':' + s.roomType);
    // Fight.
    for (let k = 0; k < 80; k++) {
      const q = await st();
      if (q.mode !== 'playing') { route.push('mode:' + q.mode); break; }
      if (!q.list) break;
      const m = q.list.match(/@(\d+),(\d+)/);
      await aim(+m[1], +m[2]);
      const dx = +m[1] - q.px, dy = +m[2] - q.py;
      const keys = [];
      if (Math.abs(dx) > 60) keys.push(dx > 0 ? 'd' : 'a');
      if (Math.abs(dy) > 60) keys.push(dy > 0 ? 's' : 'w');
      if (keys.length) await press(keys, 260);
      await page.keyboard.press('k');
      await page.keyboard.press('q');
      await page.waitForTimeout(200);
    }
    s = await st();
    if (s.mode !== 'playing') { route.push('mode:' + s.mode); break; }
    if (s.roomType === 'exit' || s.roomType === 'boss') {
      await walk(570, 400, 9000);
      await page.keyboard.press('e');
      await page.waitForTimeout(1200);
      route.push('exit@' + (await st()).floor);
      continue;
    }
    const ds = await page.evaluate(() => ({ ...window.AETHERBORNE.room.doors }));
    const target = Object.keys(ds).find(k => ds[k] && !visited.has(ds[k])) || Object.keys(ds)[0];
    if (!target) { route.push('deadend'); break; }
    const pt = { n: [570, 60], s: [570, 740], w: [60, 400], e: [1080, 400] }[target];
    await walk(pt[0], pt[1], 12000);
  }
  return JSON.stringify({ route, s: await st() });
}

