async page => {
  const qa = (code) => page.evaluate(new Function('qa', 'return (' + code + ')'), undefined).catch(() => null);
  const state = async () => JSON.parse(await page.evaluate(() => JSON.stringify(window.AETHERBORNE.state)));
  const run = async (code) => await page.evaluate(code);
  const log = [];
  const step = async (label, code, wait = 900) => {
    await run(code);
    await page.waitForTimeout(wait);
    const s = await state();
    log.push(label + ' -> ' + JSON.stringify({ mode: s.mode, floor: s.floor, room: s.room, type: s.roomType, cleared: s.cleared }));
    return s;
  };
  // 1. Enter a combat room by teleporting into a door of a combat neighbour.
  const doors = await page.evaluate(() => ({ ...window.AETHERBORNE.room.doors }));
  const combatDoor = Object.keys(doors).find(d => doors[d]);
  await step('enter ' + combatDoor, `window.AETHERBORNE.qa.enterDoor('${combatDoor}')`);
  await step('clear', 'window.AETHERBORNE.qa.clearRoom()', 600);
  const cleared = await state();
  log.push('cleared? ' + cleared.cleared + ' enemies=' + cleared.enemies + ' shards=' + (await page.evaluate(() => document.getElementById('shard-count').textContent)));
  return JSON.stringify(log, null, 1);
}

async page => {
  const state = async () => JSON.parse(await page.evaluate(() => JSON.stringify(window.AETHERBORNE.state)));
  const run = async (code) => await page.evaluate(code);
  const log = [];
  const step = async (label, code, wait = 900) => {
    await run(code);
    await page.waitForTimeout(wait);
    const s = await state();
    const hud = await page.evaluate(() => window.AETHERBORNE.qa.hud);
    log.push(label + ' -> ' + JSON.stringify({ mode: s.mode, floor: s.floor, room: s.room, type: s.roomType, hp: Math.round(s.hp), hud }));
    return s;
  };
  // Jump to the exit room through doors, clearing each room entered.
  for (let i = 0; i < 12; i++) {
    const s = await state();
    if (s.roomType === 'exit' || s.roomType === 'boss') break;
    await step('clear ' + s.room, 'window.AETHERBORNE.qa.clearRoom()', 300);
    const doors = await page.evaluate(() => ({ ...window.AETHERBORNE.room.doors }));
    const exit = await page.evaluate(() => {
      const fd = window.AETHERBORNE.floorKeys;
      return null;
    });
    const next = Object.keys(doors).find(d => doors[d]);
    await step('door ' + next, `window.AETHERBORNE.qa.enterDoor('${next}')`, 400);
  }
  await step('to exit centre', 'window.AETHERBORNE.qa.heal(); window.AETHERBORNE.qa.teleport(570, 400)', 500);
  await step('press E', 'window.AETHERBORNE.qa.interact()', 900);
  await step('descend', 'window.AETHERBORNE.qa.interact()', 1200);
  await page.waitForTimeout(2500);
  log.push('after descend: ' + JSON.stringify(await state()));
  return JSON.stringify(log, null, 1);
}
